 void waitPreview()throws Exception{
  // A nonempty preview may still belong to the previous key; await worker and UI publication.
  var field=T9Keyboard.class.getDeclaredField("worker");field.setAccessible(true);var worker=(java.util.concurrent.ExecutorService)field.get(page);
  java.util.concurrent.CountDownLatch decoded=new java.util.concurrent.CountDownLatch(1);worker.execute(()->page.view().post(decoded::countDown));assertTrue("current local decode published",decoded.await(10,java.util.concurrent.TimeUnit.SECONDS));
  long deadline=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<deadline){if(!preview().isEmpty()&&!preview().contains("載入"))return;Thread.sleep(30);}fail("preview unavailable for "+codes());}
