 void multi(long down,int action,Rect a,Rect b,int count)throws Exception{
  MotionEvent.PointerProperties[] properties=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[count];for(int i=0;i<count;i++){properties[i]=new MotionEvent.PointerProperties();properties[i].id=i;properties[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=(i==0?a:b).centerX();coords[i].y=(i==0?a:b).centerY();coords[i].pressure=1;coords[i].size=1;}
  MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,count,properties,coords,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);try{assertTrue(ui.injectInputEvent(e,true));}finally{e.recycle();}
 }
 public void testOverlappingPointers()throws Exception{start();Rect a=keyRect(4),b=keyRect(7);long time=SystemClock.uptimeMillis();multi(time,0,a,b,1);Thread.sleep(20);multi(time,5|(1<<8),a,b,2);Thread.sleep(30);multi(time,6|(1<<8),a,b,2);Thread.sleep(20);multi(time,1,a,b,1);Thread.sleep(250);assertEquals("47",codes());report("overlap-text.json");screenshot("overlap");}
 @Override void startEndpoint()throws Exception{
  endpoint=new ServerSocket(8181,8,InetAddress.getByName("127.0.0.1"));server=new Thread(()->{while(!stop)try(Socket s=endpoint.accept()){s.setSoTimeout(5000);InputStream in=new BufferedInputStream(s.getInputStream());String first=line(in);int size=0;for(String h;!(h=line(in)).isEmpty();)if(h.toLowerCase().startsWith("content-length:"))size=Integer.parseInt(h.substring(15).trim());String content=new String(in.readNBytes(size),StandardCharsets.UTF_8);String response="{}";int code=404;
   if(first.startsWith("POST /v1/ime/sentence-candidates ")){JSONObject req=new JSONObject(content);lastRequest=req;requests++;if("t9_sentence".equals(req.optString("kind"))){String mode=stub;String draft=req.getString("draft");int epoch=req.getInt("epoch");if(mode.equals("timeout")){Thread.sleep(8500);continue;}String sentence=mode.equals("illegal")?"XYZ":draft+"。";String source=mode.equals("low")?"local":mode.equals("jev")?"jev":"gemini";response=new JSONObject().put("epoch",epoch-(mode.equals("stale")?1:0)).put("sentence",sentence).put("source",source).put("confidence",mode.equals("low")?.5:.8).put("illegal_positions",0).toString();code=200;}}
   byte[] body=response.getBytes(StandardCharsets.UTF_8);s.getOutputStream().write(("HTTP/1.1 "+code+" Fixture\r\nContent-Type: application/json\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));s.getOutputStream().write(body);s.getOutputStream().flush();
  }catch(SocketException e){}catch(Exception e){if(!stop)error=e;}},"T9LoopbackStub");server.start();
 }
