 public void testSizesMidComposition()throws Exception{
  start();t9(4);t9(7);waitPreview();String size=shell("wm size"),density=shell("wm density"),font=shell("settings get system font_scale");JSONArray steps=new JSONArray();
  try {int index=0;for(String dimensions:new String[]{"968x2376","1856x2160","2160x1856","1856x2160","968x2376"}){
   JSONObject step=new JSONObject().put("size_before",shell("wm size")).put("density_before",shell("wm density")).put("font_before",shell("settings get system font_scale")).put("codes_before",codes()).put("preview_before",preview());
   shell("wm size "+dimensions);shell("wm density 420");shell("settings put system font_scale 1.3");Thread.sleep(1800);waitPreview();
   assertEquals("composition survives actual configuration","47",codes());assertEquals("preview survives configuration",step.getString("preview_before"),preview());assertEquals("no partial commit","",foldEditorText());
   String display=dimensions.equals("968x2376")?"cover":dimensions.equals("1856x2160")?"inner":"landscape";
   step.put("size_after",shell("wm size")).put("density_after",shell("wm density")).put("font_after",shell("settings get system font_scale")).put("codes_after",codes()).put("preview_after",preview()).put("display",display);
   assertTrue(step.getString("size_after").contains(dimensions));assertTrue(step.getString("density_after").contains("420"));assertEquals("1.3",step.getString("font_after").trim());checkLabels();
   t9(11);t9(11);assertEquals("",codes());for(int k:new int[]{4,7,0,10,3,7,0})t9(k);waitPreview();assertEquals("470 370",codes());String draft=preview();inst.runOnMainSync(()->assertTrue(page.core.legal(draft,"470 370")));assertEquals("",foldEditorText());screenshot("size-"+display+"-"+(index++));tap("空白");assertEquals(draft,foldEditorText());step.put("draft",draft).put("committed",foldEditorText());
   inst.runOnMainSync(()->{var ic=service.getCurrentInputConnection();assertNotNull(ic);assertTrue(ic.deleteSurroundingText(1000,1000));});assertEquals("",foldEditorText());t9(4);t9(7);waitPreview();steps.put(step);save("size-switches.json",steps.toString());
  }}finally {String value=size.contains("Override size:")?size.split("Override size:")[1].trim():"reset";String dpi=density.contains("Override density:")?density.split("Override density:")[1].trim():"reset";shell("wm size "+value);shell("wm density "+dpi);shell("settings put system font_scale "+font.trim());Thread.sleep(1000);save("size-restored.json",new JSONObject().put("size",shell("wm size")).put("density",shell("wm density")).put("font",shell("settings get system font_scale")).toString());}
  save("size-switch-text.json",new JSONObject().put("codes",codes()).put("preview",preview()).put("editor",foldEditorText()).toString());
 }
 void checkLabels(){inst.runOnMainSync(()->{for(int k=0;k<=10;k++){TextView v=(TextView)page.view().findViewWithTag("key:t9:"+k);assertNotNull(v);assertTrue("visible key "+k,v.isShown());android.graphics.Rect clip=new android.graphics.Rect();assertTrue(v.getGlobalVisibleRect(clip));assertEquals("full key below insets",v.getHeight(),clip.height());if(v.getLayout()!=null){assertTrue("label "+k,v.getHeight()-v.getTotalPaddingTop()-v.getTotalPaddingBottom()>=v.getLayout().getHeight());assertTrue("two lines "+k,v.getLayout().getLineCount()<=2);String first=v.getText().toString().split("\n",2)[0];android.graphics.Rect glyph=new android.graphics.Rect();v.getPaint().getTextBounds(first,0,first.length(),glyph);assertTrue("horizontal glyph "+k,glyph.width()<=v.getWidth()-v.getTotalPaddingLeft()-v.getTotalPaddingRight());}}});}
 public void testPendingDecodeAcrossConfiguration()throws Exception{
  start();java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);
  var field=T9Keyboard.class.getDeclaredField("worker");field.setAccessible(true);var worker=(java.util.concurrent.ExecutorService)field.get(page);
  worker.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(entered.await(3,java.util.concurrent.TimeUnit.SECONDS));
  try{inst.runOnMainSync(()->{page.key(4,false,0,0);page.key(7,false,0,0);page.reconfigure();});}finally{release.countDown();}
  waitPreview();assertEquals("47",codes());report("pending-decode-text.json");
 }
 public void testWaitPreviewUsesCurrentDecode()throws Exception{
  start();t9(4);t9(7);waitPreview();String previous=preview();
  java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);
  var field=T9Keyboard.class.getDeclaredField("worker");field.setAccessible(true);var worker=(java.util.concurrent.ExecutorService)field.get(page);
  worker.execute(()->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(entered.await(3,java.util.concurrent.TimeUnit.SECONDS));
  try{inst.runOnMainSync(()->page.key(0,false,0,0));new Thread(()->{try{Thread.sleep(300);}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{release.countDown();}}).start();
   long started=SystemClock.uptimeMillis();waitPreview();String current=preview();save("decode-readiness.json",new JSONObject().put("previous",previous).put("expected","470").put("codes",codes()).put("draft",current).put("wait_ms",SystemClock.uptimeMillis()-started).put("worker_released",release.getCount()==0).toString());assertEquals("470",codes());inst.runOnMainSync(()->assertTrue(page.core.legal(current,"470")));
  }finally{release.countDown();}
 }
 public void testCoreBudgets()throws Exception{inst=InstrumentationRegistry.getInstrumentation();out=new File(inst.getTargetContext().getFilesDir(),"v666");out.mkdirs();long libraryResidentBefore=android.os.Debug.getPss();Class.forName("com.simon.voiceime.t9.T9Core");long libraryResident=android.os.Debug.getPss()-libraryResidentBefore;long residentBefore=android.os.Debug.getPss();long before=android.os.Debug.getNativeHeapAllocatedSize(),started=System.nanoTime();try(com.simon.voiceime.t9.T9Core core=new com.simon.voiceime.t9.T9Core()){long load=System.nanoTime()-started,heap=android.os.Debug.getNativeHeapAllocatedSize()-before;long resident=android.os.Debug.getPss()-residentBefore;List<Long> times=new ArrayList<>();for(int i=0;i<1000;i++){core.clear();long t=System.nanoTime();assertTrue(core.push(4));times.add(System.nanoTime()-t);}Collections.sort(times);save("core-budgets.json",new JSONObject().put("load_ms",load/1e6).put("heap_delta",heap).put("resident_pss_delta_kib",resident).put("library_load_pss_delta_kib",libraryResident).put("push_p50_us",times.get(500)/1e3).put("push_p95_us",times.get(950)/1e3).toString());assertTrue("push under 50 us",times.get(950)<50000);assertTrue("load under 30 ms",load<30000000);assertTrue("table heap below 3MB",heap<3000000);assertTrue("table resident below 3MB",resident*1024<3000000);}ready();bind();screenshot("core-budget-editor");readback("core-budget-text.json");}
